void os_timer_insert (TskTimeout timeout)
{
  if (os_tsk_running->is_timer_used = timeout > 0)
    {
      os_tq_insert (& os_q_timer , cast_tsk_to_tq (os_tsk_running) , timeout) ;
    }
}

/*--------------------------------------------------------------------------*/

void os_timer_remove (Tsk tsk)
{
  if (tsk->is_timer_used)
    {
      os_tq_remove (cast_tsk_to_tq (tsk)) ;

      tsk->is_timer_used = FALSE ;
    }
}

/*--------------------------------------------------------------------------*/

void os_timer_remove_z (Tsk tsk)
{
  os_q_unlink (cast_tq_to_q (cast_tsk_to_tq (tsk))) ;

  tsk->is_timer_used = FALSE ;
}

